mapper.select:
select ibb.*,pro.P_Name as projectName, pro.P_Competent_Department as pCompetentDepartment,sd.D_Name as pCompetentDepartmentName, case when pro.p_project_form_type='01' then pro.P_Committee_Approva_Document when pro.p_project_form_type='02' then pro.p_Record_File when pro.p_project_form_type='03' then pro.p_Apply_File end as projectApplyFile, pro.P_Approve_budget as pApproveBudget, pro.p_record_amount as pRecordAmount, pro.p_approval_amount as pApprovalAmount, pro.p_project_form_type as pProjectFormType, pro.p_inv_total as pInvTotal from Investment_Budget_Breakdown ibb left join Pre_Project pro on ibb.Project_ID = pro.P_ID left join SYS_Department sd on pro.P_Competent_Department = sd.D_ID
${authSql}
where 1=1
and likePname(#{params.projectName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.projectName},'%')
and ibb.state = #{params.state}
and ibb.Project_ID = #{params.projectId}
order by ibb.Create_Time desc

select details.*
from Investment_Budget_Breakdown_Details details
where details.Isb_ID = #{id}

SELECT mn.p_id AS pId, mn.p_name AS pName, mn.P_Construction_Unit AS cId, sc.c_name AS cName, sd.d_id AS dId, sd.d_name AS dName, mn.P_Approve_budget AS pApproveBudget, ibb.project_Budget_Investment_Amount AS pBudgetInvestmentAmount, COALESCE(fp.allInvestment, 0) AS allInvestment, COALESCE(bb.pBudgetInvestmentCount, 0) AS pBudgetInvestmentCount, COALESCE(cp.payApplySum, 0) + COALESCE(te.travelExpensesSum, 0) AS actualPaymentAmt FROM pre_project mn LEFT JOIN sys_company sc ON sc.c_id = mn.P_Construction_Unit LEFT JOIN SYS_Department sd ON mn.P_Competent_Department = sd.D_ID LEFT JOIN Investment_Budget_Breakdown ibb ON ibb.Project_ID = mn.P_ID AND ibb.state = 7 LEFT JOIN (SELECT p_id, SUM(fp_Received) AS allInvestment FROM Fund_Plan WHERE state = 7 GROUP BY p_id) fp ON fp.p_id = mn.p_id LEFT JOIN (SELECT brea.Project_ID, COUNT(*) AS pBudgetInvestmentCount FROM Investment_Budget_Breakdown_Details details LEFT JOIN Investment_Budget_Breakdown brea ON details.Isb_ID = brea.id WHERE brea.state = 7 GROUP BY brea.Project_ID) bb ON bb.Project_ID = mn.p_id LEFT JOIN (SELECT p_id, SUM(Pay_Apply) AS payApplySum FROM con_pay WHERE Pay_State = 7 AND pay_Category IN ('01', '02', '03') GROUP BY p_id) cp ON cp.p_id = mn.p_id LEFT JOIN (SELECT project_id, SUM(apply_Amount) AS travelExpensesSum FROM travel_expenses_apply WHERE approve_status = 7 GROUP BY project_id) te ON te.project_id = mn.p_id
1=1
and likePname(#{params.pName},mn.P_Id)=true
and likeCname(#{params.cName},sc.C_Id)=true
and mn.P_Name like concat('%',#{params.pName},'%')
and sc.c_name like concat('%',#{params.cName},'%')
and mn.P_Name in
#{pName}
and sc.c_name in
#{cName}
and mn.P_Approve_budget in
#{pApproveBudget}
and ibb.project_Budget_Investment_Amount in
#{pBudgetInvestmentAmount}
and fp.allInvestment in
#{allInvestment}
and COALESCE(cp.payApplySum, 0) + COALESCE(te.travelExpensesSum, 0) in
#{actualPaymentAmt}
